import{_ as n,C as a,c as s,o as l,aj as c,j as t,G as o,a as h,w as d}from"./chunks/framework.Bfdr4H5E.js";const g="/sk/images/TradingView-$15-Sign-up.webp",u="/sk/images/TradingView-First-Look.webp",p="/sk/images/TradingView-Chart-Layout.webp",m="/sk/images/TradingView-Top-Menu.webp",w="/sk/images/Drawing-Tools.webp",f="/sk/images/TradingView-Right-Panel.webp",y="/sk/images/TV-Stock-Screener.webp",T="/sk/images/TV-Pine-Editor.webp",b="/sk/images/TV-Strategy-Tester.webp",k="/sk/images/TV-Trading-Panel.webp",v="/sk/images/TV-Paper-Trading.webp",P="/sk/images/TV-Dhan-Trading.webp",A=JSON.parse('{"title":"Charting Platform","description":"","frontmatter":{"outline":"deep","prev":{"text":"Chart Timeframes","link":"/trading-with-pav/chart-Timeframes"},"next":{"text":"TradingView – Chart Area Basics & Settings","link":"/trading-with-pav/tradingview-chart-area-basics-settings"}},"headers":[],"relativePath":"trading-with-pav/charting-platform.md","filePath":"trading-with-pav/charting-platform.md"}'),_={name:"trading-with-pav/charting-platform.md"};function S(C,e,V,I,L,x){const r=a("GraphComment"),i=a("ClientOnly");return l(),s("div",null,[e[0]||(e[0]=c('<h1 id="charting-platform" tabindex="-1">Charting Platform <a class="header-anchor" href="#charting-platform" aria-label="Permalink to &quot;Charting Platform&quot;">​</a></h1><p>In this article will discover how choosing the right charting platform to view price and carry out analysis is critical to your success.</p><div class="info custom-block"><p class="custom-block-title">Table of Content</p><nav class="table-of-contents"><ul><li><a href="#how-to-sign-up-to-get-30-credit-and-create-a-free-tradingview-account">How to sign up to get 30$ credit and create a FREE TradingView account.</a></li><li><a href="#overview-of-all-the-tools-tradingview-layout">Overview of all the tools &amp; TradingView Layout.</a><ul><li><a href="#_1-center-chart">1. Center - Chart.</a></li><li><a href="#_2-top-menu-panel-search-timeframe-indicators-etc">2. Top Menu/Panel - Search, Timeframe, Indicators etc.</a></li><li><a href="#_3-left-menu-panel-drawing-tools">3. Left Menu/Panel - Drawing Tools.</a></li><li><a href="#_4-right-menu-panel-watchlist-order-panel-dom">4. Right Menu/Panel - Watchlist, Order Panel, DOM.</a></li><li><a href="#_5-bottom-menu-panel-stock-screener-trading-panel-etc">5. Bottom Menu/Panel - Stock Screener, Trading Panel etc.</a></li></ul></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><p>Nowadays, trading platforms are everywhere, so knowing which has the right features and which to choose for trading isn’t as easy as it seems. However, in the past few years, one platform has climbed to the top. I’m talking about <a href="https://www.tradingview.com/gopro/?share_your_love=YSTC" target="_blank" rel="noreferrer">TradingView</a>, ring a bell?</p><p>Combining highly advanced charts with a whole suite of social features, TradingView has cemented itself as one of the top Stocks, Futures, Crypto, Indices, Forex charting platforms.</p><p>It’s easy to use, packed with amazing features not found on most other platforms, and best of all, completely FREE.</p><p>Today I’m going to give you a complete walk-through of how to use TradingView along with its many features.</p><p>I’ve used TradingView for 3 years. I made the switch from Zerodha&#39;s Trading view back in 2020. So I know the tips, tricks, and little secrets that will help you to get started.</p><p>TradingView has updated layout of menu as of 04 Aug 2023. But not much has changed that the following article needs to be updated.</p><h2 id="how-to-sign-up-to-get-30-credit-and-create-a-free-tradingview-account" tabindex="-1">How to sign up to get 30$ credit and create a FREE TradingView account. <a class="header-anchor" href="#how-to-sign-up-to-get-30-credit-and-create-a-free-tradingview-account" aria-label="Permalink to &quot;How to sign up to get 30$ credit and create a FREE TradingView account.&quot;">​</a></h2><ol><li>On this site footer (Bottom) there is a link called TradingView under Trading Platforms and above social media links. Also you can <a href="https://www.tradingview.com/gopro/?share_your_love=YSTC" target="_blank" rel="noreferrer">click here</a>.</li><li>Clicking on it will take you to TradingView site and give you a welcome banner &amp; click on the signup button of welcome banner will take you to signup page.</li><li>Enter your details either through social media like google, Facebook etc. We personally recommend through Email as privacy is our concern.</li><li>After clicking Email enter you info such as preferred username, email and password.</li><li>Click on create account. voila your TradingView account is created and you get 30$ to use in the future if you need extra features.</li><li>Needless to say for new trader/user FREE TradingView is more than enough.</li></ol><p><a href="https://www.tradingview.com/pricing/?share_your_love=YSTC" target="_blank" rel="noreferrer"><img src="'+g+'" alt="TradingView-$15-Sign-up" title="click here to open account"></a></p><h2 id="overview-of-all-the-tools-tradingview-layout" tabindex="-1">Overview of all the tools &amp; TradingView Layout. <a class="header-anchor" href="#overview-of-all-the-tools-tradingview-layout" aria-label="Permalink to &quot;Overview of all the tools &amp; TradingView Layout.&quot;">​</a></h2><p><img src="'+u+'" alt="TradingView-First-Look"></p><p>The above image is how a new account of TradingView looks. Lets look at the layout of this charting platform.</p><p><img src="'+p+'" alt="TradingView-Chart-Layout"></p><p>As you can see in the above image. There are 5 Key areas on chart as follows:</p><ol><li>Center - Chart. (Blue Color)</li><li>Top Menu/Panel- Symbol Search, Timeframe, Indicators etc. (Red Color)</li><li>Left Menu/Panel - Drawing Tools. (Green Color)</li><li>Right Menu/Panel - Watchlist, Order Panel, DOM. (Yellow)</li><li>Bottom Menu/Panel - Stock Screener, Trading Panel etc. (White Color)</li></ol><p>Lets explorer all the 5 areas. Will only detail what tools are needed for analysis whereas you are free to explorer the platform.</p><h3 id="_1-center-chart" tabindex="-1">1. Center - Chart. <a class="header-anchor" href="#_1-center-chart" aria-label="Permalink to &quot;1. Center - Chart.&quot;">​</a></h3><p>This is self explanatory whatever chart you want is displayed here. Candlestick chart is main go-to chart and for RSI Divergence or generalize idea of market direction we use Line chart.</p><p>Other charts which are available in TradingView are Bars, Hollow Candles, Columns, Area, High-Low, Heikin Ashi, Renko, Line Break, Kagi, Point &amp; Figure, Range etc. Chart can be zoomed in and out with mouse scroll and also with dragging the price scale up/down to zoom vertical and dragging the time scale right/left to zoom horizontal. To reset chart press Alt+R or right click &gt; Reset Chart.</p><h3 id="_2-top-menu-panel-search-timeframe-indicators-etc" tabindex="-1">2. Top Menu/Panel - Search, Timeframe, Indicators etc. <a class="header-anchor" href="#_2-top-menu-panel-search-timeframe-indicators-etc" aria-label="Permalink to &quot;2. Top Menu/Panel - Search, Timeframe, Indicators etc.&quot;">​</a></h3><p><img src="'+m+'" alt="TradingView-Top-Menu"></p><p>The above image shows Top menu option in rectangle colored which when clicked displays panels as shown in respective colored numbers. Lets go through each one.</p><ol><li><strong>Symbol Search</strong> - In the top left (red border) shows the current instrument AAPL when clicked opens a dialogue in the image no. 1 in red color. Here you can search any script by name in the search. TradingView offers Stocks, Funds, Futures, Forex, Crypto, Indices, Bonds and Economy.<br> TradingView offers exchange data Free (Sometimes delayed check before trading) as well as Paid through add-on.</li><li><strong>Timeframe</strong> - In the top left (green border) shows the current chart timeframe. TradingView offers 1m, 3m, 5m, 15m, 30m, 45m, 1H, 2H, 3H, 4H, 1D, 1W, 1M and 3,6,12M for Free. For Paid Plan you add custom timeframe like 10m or 2m etc. as well as seconds timeframe also get unlocked.</li><li><strong>Chart Type</strong> - In the top left (blue border) shows the current chart type i.e.. candlestick in the image. Bars, Candle, Hollow Candles, Columns, Line, Line with markers, Step line, Area, Baseline, High-Low, Heikin Ashi, Renko, Line Break, Kagi, Point &amp; Figure and Range are available on TradingView.</li><li><strong>Indicators, Metrics &amp; Strategies</strong> - After chart type to the right of it is Indicators (teal border). In the you can find all the Free indicators in the Technicals some of the most popular ones are moving average, MACD, RSI etc. In the Profiles tab contains Volume Profile which you only get with Monthly Paid Subscription.<br> If you want Volume Profile for Lifetime on TradingView then no need to look elsewhere we offer custom built Volume Profile with S/R Zones and VWAP tools <a href="/sk/volume-profile-tools/">Click Here to Know More</a>.</li><li><strong>Select Layout</strong> - In the top right (Fuchsia color aka pinkish) is Layouts button clicking it gives the menu no. 5 in the image. You can see in that menu single layout is one. 2nd one is double layout Left/Right or Up/Down charts etc. till 8th one is with 8 charts in one single screen.<br> Plus in the bottom you can sync Symbol, Interval (Timeframe), Crosshair and time of multiple layouts. Single Layout is Free other are available in Paid.</li><li><strong>Save Layouts</strong> - In the top right (orange color) gives the menu no. 6 in the image. Whatever layout you create single, double or eight layouts here you can save it also saves drawing from the chart and auto save.<br> There is also an option to export chart data like OHLC and volume to csv format to view in other chart platforms or in excel sheet to develop offline strategies.</li><li><strong>Chart Settings</strong> - Here you can set how the chart info is displayed to you. As you can see in the image menu no. 7 settings available are Symbol, Status line, Scales, Appearance, Trading, Events. Will Discus what settings are best in next article.</li></ol><h3 id="_3-left-menu-panel-drawing-tools" tabindex="-1">3. Left Menu/Panel - Drawing Tools. <a class="header-anchor" href="#_3-left-menu-panel-drawing-tools" aria-label="Permalink to &quot;3. Left Menu/Panel - Drawing Tools.&quot;">​</a></h3><p><img src="'+w+'" alt="Drawing-Tools"></p><p>The above image shows Left panel menu option which is dedicated to Drawing tools when clicked displays panels as shown in the image 1-7 and 9, 10 respective. Will later teach some of the tools which we gonna learn in our course. Lets go through each one.</p><ol><li><strong>Cursors</strong> - Type of cursor you want displayed in charts, available are Cross, Dot, Arrow and Eraser to delete the drawings drawn on chart.</li><li><strong>Trend Line Tools</strong> - This panel is dedicated to trendlines. The important ones are Horizontal Line &amp; Ray, Vertical Line.</li><li><strong>Gann and Fibonacci Tools</strong> - This panel contains variety of tools from Fibonacci and Gann. We only use Fib Retracement. You can explore many of them but personally we don&#39;t find their use for profitable trading.</li><li><strong>Geometric Shapes</strong> - This ones contains all geometric shapes. From this we use Brush, Rectangle and Path.</li><li><strong>Annotation Tools</strong> - These ones exist to draw notes on chart. Usefully for Analysis, Teaching, and record keeping etc.</li><li><strong>Patterns</strong> - These are the patterns you draw on chart to determine the target according to patterns. Check our <a href="https://ystc.in/ebooks/" target="_blank" rel="noreferrer">eBooks</a> which has poster of Chart Patterns dictated with Price Action.</li><li><strong>Prediction and Measurement Tools</strong> - All the Risk Reward tools, Target and stoploss measurements are located here also Forecast and projection.</li><li><strong>Measure</strong> - Quickly measure with ruler on chart.</li><li><strong>Magnets</strong> - Snaps drawings to OHLC points with precision instead of manual drawing. Available option are Weak and Strong Magnet.</li><li><strong>Delete</strong> - This deletes the drawings as well as indicators and available options are Remove drawings, Indicator or Remove both.</li></ol><h3 id="_4-right-menu-panel-watchlist-order-panel-dom" tabindex="-1">4. Right Menu/Panel - Watchlist, Order Panel, DOM. <a class="header-anchor" href="#_4-right-menu-panel-watchlist-order-panel-dom" aria-label="Permalink to &quot;4. Right Menu/Panel - Watchlist, Order Panel, DOM.&quot;">​</a></h3><p><img src="'+f+'" alt="TradingView-Right-Panel"></p><p>The above image shows Right panel menu option when clicked displays panels as shown in the image 1-5. As you can notice many option that we didn&#39;t cover because they are not important but you may explorer yourself. Lets go through each one.</p><ol><li><strong>Watchlist, Details and News</strong> - Watchlist is a place where you save a list of instruments (Scripts) to switch your chart quickly just like how you favorite your music playlist to go through your songs instead of searching it.<br> In the image no. 1 you can see watchlist and below watchlist you can see the details of the current selected chart i.e. State bank of India. Some of the imp details of a script you can view quickly are Bid x Ask, Price ranges, Latest News, Key Stats, Earnings, Dividends, Performance and Profile.</li><li><strong>Alerts</strong> - You can place alerts to price or indicator when a condition is met which helps you relaxed and only get into action when needed. For Free account you get 1 Price Alert and 1 Indicator Alert to place. If you want more alerts then upgrade your TradingView plan. Use the 15$ you got when you signed up through our link if not <a href="https://www.tradingview.com/gopro/?share_your_love=YSTC" target="_blank" rel="noreferrer">Click here</a>.</li><li><strong>Calendar</strong> - Calendar is a place where you get Economic Calendar of your select countries which markets you trade and also get Earnings Calendar below the Economic Calendar. No need to leave the charting platform.</li><li><strong>Order Panel</strong> - In this panel you can place orders for current script on chart i.e. in image you can see selected market is NSE:SBI and connected broker is Dhan. You can place Buy or Sell orders from here. Will explorer about orders in dedicated article.</li><li><strong>DOM</strong> - In this panel you can see Depth of Market here you can see the how the price discovery is happening.</li></ol><h3 id="_5-bottom-menu-panel-stock-screener-trading-panel-etc" tabindex="-1">5. Bottom Menu/Panel - Stock Screener, Trading Panel etc. <a class="header-anchor" href="#_5-bottom-menu-panel-stock-screener-trading-panel-etc" aria-label="Permalink to &quot;5. Bottom Menu/Panel - Stock Screener, Trading Panel etc.&quot;">​</a></h3><p>Now on the bottom there are 4 tabs they are Stock Screener, Pine Editor, Strategy Tester and Trading Panel.</p><p><img src="'+y+'" alt="TV-Stock-Screener"></p><p>The above image shows <strong>Stock Screener</strong> will see the use of screener in later articles but in short it is used to filter stocks according to your criteria.</p><p><img src="'+T+'" alt="TV-Pine-Editor"></p><p>The second tab is <strong>Pine Editor</strong> which is the most popular feature of TradingView i.e. you can create your own Indicators and Strategy and you can publish it as an open source public, Private or Invite only. Pine Scripts are basically TradingView&#39;s custom version of Python Language. So if you know python you can create your own custom indicators scripts and if you don&#39;t know python you can still learn pine script from the documentation.</p><p><img src="'+b+'" alt="TV-Strategy-Tester"></p><p>The third tab is <strong>Strategy Tester</strong> here you can get the strategy data of historical test of how you strategy performed i.e. Profits and losses so that you can decide weather you need to tweak your strategy or not.</p><p><img src="'+k+'" alt="TV-Trading-Panel"></p><p>The last one is <strong>Trading Panel</strong> here you connect to your broker so that you can trade from TradingView itself. The below image shows Paper trading which is dummy trading for new trader to test their trading skills so that no huge losses are made in the beginning</p><p><img src="'+v+'" alt="TV-Paper-Trading"></p><p>You can also connect to <strong>Dhan broker</strong> for Indian market. First Indian broker to be integrated to TradingView Platform. Below is the image of Dhan connected to TradingView.</p><p><img src="'+P+'" alt="TV-Dhan-Trading"></p><p>If you don&#39;t have Dhan broker Account then <a href="https://invite.dhan.co/?invite=KJXFR31859" target="_blank" rel="noreferrer">click here</a> to open the account Free. That&#39;s it for TradingView Platform. If you use any different charting Platform then the basic Functionality you learned</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',49)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/NDXMC6_oUKw",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[h("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),o(i,null,{default:d(()=>[o(r)]),_:1})])}const F=n(_,[["render",S]]);export{A as __pageData,F as default};
